<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {NButton,NInput,NModal,NSelect,NCheckbox} from 'naive-ui'
import {membersApi,type Member} from '../api/memberClaims'
import {request} from '../api/client'
import {money,kinds,type Account,type Location} from '../api/funds'
const props=defineProps<{mode:'accounts'|'locations';accounts:Account[];locations:Location[];editable:boolean}>()
const emit=defineEmits<{changed:[]}>()
const show=ref(false),id=ref(''),error=ref(''),busy=ref(false)
const members=ref<Member[]>([]),locationKind=ref('physical'),externalKind=ref('supplier'),active=ref(true),member=ref<string|null>(null),custodyShow=ref(false),custodyId=ref('')
onMounted(async()=>{try{members.value=await membersApi.list()}catch(e){error.value=(e as Error).message}})
const externalOptions=[{value:'supplier',label:'供应商'},{value:'customer',label:'客户'},{value:'opening',label:'期初'},{value:'loss',label:'损耗'},{value:'adjustment_gain',label:'调增'},{value:'adjustment_loss',label:'调减'}]
function custody(l:Location){custodyId.value=l.id;member.value=l.current_custody?.member_id||null;custodyShow.value=true}
async function saveCustody(){busy.value=true;try{await request('/locations/'+custodyId.value+'/custody','POST',{member_id:member.value});custodyShow.value=false;emit('changed')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
const name=ref(''),tags=ref(''),kind=ref('asset'),isFund=ref(false),custodian=ref('')
function edit(item?:Account|Location){id.value=item?.id||'';name.value=item?.name||'';tags.value=item?.tags.join(', ')||'';kind.value=(item as Account)?.kind||'asset';isFund.value=(item as Account)?.is_fund||false;custodian.value=(item as Location)?.custodian_label||'';locationKind.value=(item as Location)?.kind||'physical';externalKind.value=(item as Location)?.external_kind||'supplier';active.value=(item as Location)?.active??true;error.value='';show.value=true}
async function save(){busy.value=true;error.value='';try{const body:Record<string,unknown>={name:name.value,tags:[...new Set(tags.value.split(/[,，]/).map(x=>x.trim()).filter(Boolean))]};if(props.mode==='locations'){body.custodian_label=custodian.value;body.kind=locationKind.value;body.external_kind=locationKind.value==='external'?externalKind.value:null;body.active=active.value;}else if(!id.value){body.kind=kind.value;body.is_fund=kind.value==='asset'&&isFund.value}await request(`/${props.mode}${id.value?'/'+id.value:''}`,id.value?'PATCH':'POST',body);show.value=false;emit('changed')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><div class="toolbar"><h2>{{mode==='accounts'?'记账对象':'存货地点目录'}}</h2><NButton v-if="editable" @click="edit()">新建</NButton></div><p v-if="mode==='locations'" class="muted">实际地点记录库存，外部端点用于供应商、客户、期初、损耗和调整。</p><div class="table-wrap"><table><thead><tr><th>名称</th><th>{{mode==='accounts'?'类别':'保管人'}}</th><th v-if="mode==='accounts'">资金对象</th><th>标签</th><th v-if="mode==='accounts'">账面余额（元）</th><th v-if="editable">操作</th></tr></thead><tbody><template v-if="mode==='accounts'"><tr v-for="a in accounts" :key="a.id"><td>{{a.name}}<small>{{a.id}}</small></td><td>{{kinds[a.kind]}}</td><td>{{a.is_fund?'是':'否'}}</td><td><span v-for="tag in a.tags" :key="tag" class="tag">{{tag}}</span></td><td>{{money(a.balance_minor)}}</td><td v-if="editable"><NButton size="small" @click="edit(a)">编辑</NButton></td></tr></template><template v-else><tr v-for="a in locations" :key="a.id"><td>{{a.name}}<small>{{a.id}}</small></td><td>{{a.kind==='physical'?'实际地点':'外部端点'}}<small>{{a.current_custody?.member_name||a.custodian_label||'未指定成员'}}；{{a.active?'启用':'停用'}}</small></td><td><span v-for="tag in a.tags" :key="tag" class="tag">{{tag}}</span></td><td v-if="editable"><NButton size="small" @click="edit(a)">编辑</NButton><NButton v-if="a.kind==='physical'" size="small" @click="custody(a)">成员保管</NButton></td></tr></template></tbody></table></div><NModal v-model:show="show" preset="card" :title="id?'编辑资料':'新建资料'" class="dialog"><label>名称<NInput v-model:value="name"/></label><label>标签（逗号分隔）<NInput v-model:value="tags"/></label><template v-if="mode==='accounts'&&!id"><label>类别<NSelect v-model:value="kind" :options="Object.entries(kinds).map(([value,label])=>({value,label}))"/></label><NCheckbox :checked="isFund" :disabled="kind!=='asset'" @update:checked="isFund=$event">资金对象（仅资产类别）</NCheckbox></template><template v-if="mode==='locations'"><label>地点类型<NSelect v-model:value="locationKind" :options="[{label:'实际地点',value:'physical'},{label:'外部端点',value:'external'}]"/></label><label v-if="locationKind==='external'">外部用途<NSelect v-model:value="externalKind" :options="externalOptions"/></label><label>保管备注<NInput v-model:value="custodian"/></label><NCheckbox v-model:checked="active">启用</NCheckbox></template><p v-if="error" class="error">{{error}}</p><div class="actions"><NButton type="primary" :loading="busy" @click="save">保存</NButton></div></NModal><NModal v-model:show="custodyShow" preset="card" title="维护当前保管成员" class="dialog"><NSelect v-model:value="member" clearable placeholder="清空表示不指定成员" :options="members.map(m=>({label:m.name,value:m.id}))"/><p class="error">{{error}}</p><NButton :loading="busy" @click="saveCustody">保存保管关系</NButton></NModal></template>
